for(const m of state.messages){if(!m.conversationId){m.conversationId=`legacy-${m.id}`;state.threads.push({id:m.conversationId,topic:m.summary||'Existing message',contact:m.contact||'',customer:m.customer||'',relevance:m.relevance||'Needs review',status:m.status||'Needs reply',owner:m.owner||'Unassigned',priority:m.urgency||'Normal',nextAction:m.action||'',due:m.due||'',created:m.date||'',legacy:true});}}
