const cloudCollections={customers:'customer',tasks:'task',threads:'message_thread',messages:'message',followups:'followup',campaigns:'campaign',improvements:'improvement',activity:'activity'};
let cloudBaseline=new Map(),cloudSaveQueue=Promise.resolve();
function blankCloudState(members,operational,finance){const next=starter();for(const name of [...Object.keys(cloudCollections),'finance'])next[name]=[];next.customers=operational.filter(r=>r.record_type==='customer').map(r=>r.payload);next.tasks=operational.filter(r=>r.record_type==='task').map(r=>r.payload);next.threads=operational.filter(r=>r.record_type==='message_thread').map(r=>r.payload);next.messages=operational.filter(r=>r.record_type==='message').map(r=>r.payload);next.followups=operational.filter(r=>r.record_type==='followup').map(r=>r.payload);next.campaigns=operational.filter(r=>r.record_type==='campaign').map(r=>{const c=r.payload;if(c.workflow==='Owner review')c.workflow='Submitted for review';if(c.workflow==='Approved to send')c.workflow='Approved';c.reviewer||='Owner';c.reviewNotes||='';return c;});next.improvements=operational.filter(r=>r.record_type==='improvement').map(r=>r.payload);next.activity=operational.filter(r=>r.record_type==='activity').map(r=>r.payload);next.finance=finance.map(r=>r.payload);next.permissions=members.map(m=>({user_id:m.user_id,name:m.display_name,role:m.role,active:m.active,finance_access:m.finance_access,finance:m.finance_access?'Full access':'No financial access'}));for(const c of next.campaigns){c.reviewer||='Owner';c.reviewNotes||='';}return next;}
function resetCloudWorkspace(){cloudLoadGeneration++;cloudLoadPromise=null;cloudSession=null;cloudMember=null;cloudReady=false;cloudLoading=false;cloudStatus='signed-out';cloudError='';currentUser='';state=starter();cloudBaseline.clear();nav();render();}
async function useCloudSession(session){if(!session){resetCloudWorkspace();return;}const changed=cloudSession?.user.id!==session.user.id;if(changed){cloudLoadGeneration++;cloudLoadPromise=null;cloudReady=false;cloudMember=null;state=starter();cloudBaseline.clear();}cloudSession=session;if(!cloudReady){cloudLoading=true;cloudStatus='checking';}return loadCloudWorkspace();}
async function loadCloudWorkspace(){if(!cloudSession)return;if(cloudLoadPromise)return cloudLoadPromise;const userId=cloudSession.user.id,generation=++cloudLoadGeneration;cloudLoading=true;cloudError='';if(!cloudReady){cloudStatus='checking';nav();render();}const pending=(async()=>{const memberResult=await backendClient.from('team_members').select('user_id,display_name,role,active,finance_access').eq('user_id',userId).maybeSingle();if(generation!==cloudLoadGeneration||cloudSession?.user.id!==userId)return;if(memberResult.error)throw memberResult.error;if(!memberResult.data||!memberResult.data.active){cloudMember=null;cloudReady=false;cloudStatus='inactive';state=starter();cloudBaseline.clear();return;}cloudMember=memberResult.data;currentUser=cloudMember.display_name;const [membersResult,operationalResult,financeResult]=await Promise.all([backendClient.from('team_members').select('user_id,display_name,role,active,finance_access').eq('active',true),backendClient.from('workspace_records').select('record_type,record_key,customer_key,payload').order('updated_at',{ascending:true}).limit(5000),cloudMember.finance_access?backendClient.from('finance_records').select('record_key,customer_key,record_kind,payload').order('updated_at',{ascending:true}).limit(5000):Promise.resolve({data:[],error:null})]);if(generation!==cloudLoadGeneration||cloudSession?.user.id!==userId)return;for(const result of [membersResult,operationalResult,financeResult])if(result.error)throw result.error;const ops=operationalResult.data||[],fin=financeResult.data||[];state=blankCloudState(membersResult.data||[],ops,fin);cloudBaseline.clear();for(const row of ops)cloudBaseline.set(row.record_type+':'+row.record_key,JSON.stringify(row.payload));for(const row of fin)cloudBaseline.set('finance:'+row.record_key,JSON.stringify(row.payload));cloudReady=true;cloudStatus='ready';storageAvailable=true;queueCloudSave();})();cloudLoadPromise=pending;try{await pending;}catch(error){if(generation===cloudLoadGeneration){cloudReady=false;cloudMember=null;cloudStatus='error';cloudError=error?.message||String(error);storageAvailable=false;console.error('Workspace load failed',error);}throw error;}finally{if(generation===cloudLoadGeneration){cloudLoading=false;cloudLoadPromise=null;nav();render();}}}
async function refreshCloudWorkspaceOnReturn(force=false){if(!cloudEnabled||!backendClient||document.visibilityState==='hidden')return;if(cloudResumePromise)return cloudResumePromise;const now=Date.now();if(!force&&now-lastCloudResumeAt<2500)return;lastCloudResumeAt=now;cloudResumePromise=(async()=>{const {data,error}=await backendClient.auth.getSession();if(error)throw error;await useCloudSession(data.session);})();try{await cloudResumePromise;}catch(error){cloudLoading=false;if(cloudSession){cloudReady=false;cloudMember=null;cloudStatus='error';cloudError=error?.message||String(error);nav();render();}console.error('Workspace resume refresh failed',error);}finally{cloudResumePromise=null;}}
async function bootstrapCloud(){if(!cloudEnabled)return;if(!backendClient){cloudLoading=false;cloudStatus='error';cloudError='Dashboard API client did not load. Check the page files and reload.';render();return;}cloudLoading=true;cloudStatus='checking';cloudError='';try{const {data,error}=await backendClient.auth.getSession();if(error)throw error;await useCloudSession(data.session);}catch(error){cloudLoading=false;cloudReady=false;cloudStatus='error';cloudError=error?.message||String(error);storageAvailable=false;console.error('Dashboard API setup error',error);nav();render();}backendClient.auth.onAuthStateChange((_event,session)=>{queueMicrotask(()=>{useCloudSession(session).catch(error=>console.error('Workspace auth refresh failed',error));});});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshCloudWorkspaceOnReturn();});window.addEventListener('focus',()=>refreshCloudWorkspaceOnReturn());}
function cloudAuthGate(){const loading=cloudLoading||cloudStatus==='checking',inactive=cloudStatus==='inactive',failed=cloudStatus==='error';const title=loading?'Restoring your shared workspace…':inactive?'Your account is not active yet':failed?'Could not load your workspace':'Sign in to your team workspace';const message=loading?'Checking your team access and loading the latest shared records.':inactive?'This account has no active Relocation Vietnam membership. Ask an owner or general manager to invite you.':failed?'The dashboard could not verify access or load shared data. Check your connection and try again. '+cloudError:'Sign in with an account invited to the team workspace. Local demo records are not shown or uploaded in cloud mode.';const action=failed&&cloudSession?'<button class="button primary" data-action="retry-cloud-load">Retry loading workspace</button>':!cloudSession?'<button class="button primary" data-action="profile-picker">Sign in</button>':'';return '<section class="panel auth-gate"><div class="panel-body"><p class="eyebrow">'+(loading?'RESTORING WORKSPACE':inactive?'ACCESS APPROVAL':failed?'CONNECTION ISSUE':'SECURE TEAM WORKSPACE')+'</p><h1>'+esc(title)+'</h1><p>'+esc(message)+'</p>'+action+'</div></section>';}
function queueCloudSave(){if(!cloudReady||!cloudSession)return;const snapshot=JSON.parse(JSON.stringify(state));cloudSaveQueue=cloudSaveQueue.then(async()=>{const current=new Map();for(const [field,type] of Object.entries(cloudCollections))for(const item of snapshot[field]||[])if(item?.id)current.set(`${type}:${item.id}`,{type,key:String(item.id),payload:item,customer:item.customer||item.id});for(const item of snapshot.finance||[])if(item?.id)current.set(`finance:${item.id}`,{type:'finance',key:String(item.id),payload:item,customer:item.customer||null});for(const [key,record] of current){if(cloudBaseline.get(key)===JSON.stringify(record.payload))continue;let result;if(record.type==='finance')result=await backendClient.from('finance_records').upsert({record_key:record.key,customer_key:record.customer,record_kind:(({invoice:'invoice',receipt:'payment',payment:'payment',quote:'quote',expense:'expense',commission:'commission'})[String(record.payload.kind||'').toLowerCase()]||'other'),payload:record.payload,updated_at:new Date().toISOString()},{onConflict:'record_key'});else result=await backendClient.from('workspace_records').upsert({record_type:record.type,record_key:record.key,customer_key:record.customer,payload:record.payload,updated_at:new Date().toISOString()},{onConflict:'record_type,record_key'});if(result.error)throw result.error;cloudBaseline.set(key,JSON.stringify(record.payload));}for(const [key,oldPayload] of [...cloudBaseline])if(!current.has(key)){const [type,...keyParts]=key.split(':');const recordKey=keyParts.join(':');const result=type==='finance'?await backendClient.from('finance_records').delete().eq('record_key',recordKey):await backendClient.from('workspace_records').delete().eq('record_type',type).eq('record_key',recordKey);if(result.error)throw result.error;cloudBaseline.delete(key);}}).catch(error=>{storageAvailable=false;console.error('Dashboard cloud save failed',error);toast(`Could not sync changes: ${error.message||'check your connection and access'}`);});}
async function bootstrapCloud(){if(!cloudEnabled)return;if(!backendClient){cloudError='Dashboard API client did not load. Check the page files and reload.';render();return;}cloudError='';try{const {data,error}=await backendClient.auth.getSession();if(error)throw error;cloudSession=data.session;if(cloudSession)await loadCloudWorkspace();else{cloudReady=false;state=starter();nav();render();}}catch(error){cloudReady=false;storageAvailable=false;console.error('Dashboard API setup error',error);render();}backendClient.auth.onAuthStateChange((_event,session)=>{queueMicrotask(async()=>{cloudSession=session;if(session){try{await loadCloudWorkspace();}catch(error){cloudReady=false;storageAvailable=false;console.error('Workspace load failed',error);toast(`Could not load workspace: ${error.message||'check team approval'}`);render();}}else{cloudMember=null;cloudReady=false;currentUser='';state=starter();cloudBaseline.clear();nav();render();}});});}
