function closeDialog(dialog){if(typeof dialog.close==='function'&&dialog.open&&!dialog.classList.contains('dialog-fallback-open')){dialog.close();finishDialogClose();return;}dialog.removeAttribute('open');dialog.classList.remove('dialog-fallback-open');finishDialogClose();}
