function openServiceForm(customerId,index=null){const c=customer(customerId);if(!c)return;const track=index===null?null:c.tracks[Number(index)],dialog=$('#detail');dialog.dataset.kind='service-form';dialog.dataset.customer=customerId;dialog.innerHTML=`<form id="service-form" data-customer="${esc(customerId)}" data-track="${index===null?'':index}"><div class="dialog-head"><div><p class="eyebrow">${track?'ADD':'ADD'} · CUSTOMER SERVICE</p><h2>${track?'Add a milestone':'Add a service track'}</h2><p class="quiet-note">Add only services confirmed for this customer. You can change the suggested name.</p></div><button type="button" class="icon-button" data-action="close">×</button></div><div class="form-content"><div class="form-grid">${track?`<label>Milestone name<input name="name" required maxlength="120" placeholder="What needs to happen?"></label><label>Status<select name="status">${statusSelect(milestoneStatuses,'Needs confirmation')}</select></label><label>Waiting on<select name="waitingOn">${waitingOnSelect()}</select></label><label>Target date<input name="due" type="date"></label><label class="form-grid-wide">Evidence / handoff note<textarea name="evidence" rows="2" placeholder="Source, result, or what the next person needs to know"></textarea></label>`:`<label>Service or track<input name="name" list="service-suggestions" required maxlength="120" placeholder="Choose or enter a confirmed service"><datalist id="service-suggestions">${serviceSuggestions.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></label><label>Status<select name="status">${statusSelect(taskStatuses,'Needs confirmation')}</select></label><label>Owner<select name="owner">${ownersSelect('Unassigned')}</select></label><label>Target date<input name="due" type="date"></label><label class="form-grid-wide">Next step<input name="next" value="Confirm the next step" maxlength="240"></label><label class="form-grid-wide inline-check"><input type="checkbox" name="suggested" value="yes"> Add editable suggested checkpoints for this service</label>`}</div><div class="dialog-actions"><button type="button" class="button secondary" data-action="close">Cancel</button><button class="button primary" type="submit">${track?'Add milestone':'Add service'}</button></div></div></form>`;showDialog(dialog);}
