document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;if(button.dataset.action==='profile-picker'){loginDialog();return;}if(button.dataset.action==='select-profile'){const select=$('#profile-select');currentUser=select?.value||'';try{if(currentUser)localStorage.setItem('rv-dashboard-current-user',currentUser);}catch(error){storageAvailable=false;}nav();closeDialog($('#detail'));render();toast('Local demo profile selected.');return;}if(button.dataset.action==='sign-out-profile'){currentUser='';try{localStorage.removeItem('rv-dashboard-current-user');}catch(error){storageAvailable=false;}nav();closeDialog($('#detail'));render();toast('Local demo profile cleared.');}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id;let record;if(action==='complete-improvement'||action==='reopen-improvement'){record=state.improvements.find(x=>x.id===id);if(record){record.status=action==='complete-improvement'?'Completed':'Under review';record.completedAt=action==='complete-improvement'?today():'';log(`${action==='complete-improvement'?'Completed':'Reopened'} feedback: ${record.title}`);save();render();toast(action==='complete-improvement'?'Feedback marked completed.':'Feedback reopened for review.');}}else if(action==='complete-followup'||action==='reopen-followup'){record=state.followups.find(x=>x.id===id);if(record){record.status=action==='complete-followup'?'Completed':'To do';record.completedAt=action==='complete-followup'?today():'';log(`${action==='complete-followup'?'Completed':'Reopened'} follow-up: ${record.title}`,record.customer);save();render();toast(action==='complete-followup'?'Follow-up marked completed.':'Follow-up reopened.');}}else if(['submit-campaign-review','approve-campaign','request-campaign-changes','complete-campaign','reopen-campaign'].includes(action)){record=state.campaigns.find(x=>x.id===id);if(record){if(action==='submit-campaign-review')record.workflow='Submitted for review';if(action==='approve-campaign'||action==='request-campaign-changes'){if(!canOwnerReview()){toast('Only Owner can record the owner review in this workflow.');return;}if(action==='approve-campaign')record.workflow='Approved';else{const note=Array.from(document.querySelectorAll('[data-review-note]')).find(el=>el.dataset.reviewNote===id)?.value?.trim()||'';if(!note){toast('Add a short note explaining the requested changes.');return;}record.workflow='Changes requested';record.reviewNotes=note;}}if(action==='complete-campaign'&&record.workflow==='Approved'){record.workflow='Sent';record.sentAt=today();}if(action==='reopen-campaign')record.workflow='Drafting';log(`Marketing workflow updated: ${record.name} · ${record.workflow}`);save();render();toast(`Marketing status: ${record.workflow}.`);}}else if(action==='resolve-thread'||action==='reopen-thread'){record=state.threads.find(x=>x.id===id);if(record){record.status=action==='resolve-thread'?'Resolved':'Needs reply';for(const message of state.messages.filter(x=>x.conversationId===id))message.status=record.status;log(`${action==='resolve-thread'?'Resolved':'Reopened'} conversation: ${record.topic}`,record.customer);save();render();toast(action==='resolve-thread'?'Conversation resolved.':'Conversation reopened.');}}else if(action==='complete-service'||action==='reopen-service'){const c=customer(button.dataset.customer),track=c?.tracks[Number(button.dataset.track)];if(track){track.status=action==='complete-service'?'Completed':'In progress';track.completed=action==='complete-service'?today():'';c.reviewed=today();log(`${action==='complete-service'?'Completed':'Reopened'} service: ${track.name}`,c.id);save();if($('#detail').open&&$('#detail').dataset.customer===c.id)openCustomer(c.id);render();toast(action==='complete-service'?'Service marked completed.':'Service reopened.');}}});
document.addEventListener('change',e=>{if(e.target.id==='profile-select'){currentUser=e.target.value||'';}});
document.addEventListener('keydown',e=>{const dialog=$('#detail');if(!dialog.classList.contains('dialog-fallback-open'))return;if(e.key==='Escape'){e.preventDefault();closeDialog(dialog);return;}if(e.key!=='Tab')return;const focusable=Array.from(dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href],[tabindex="0"]')).filter(el=>el.getClientRects().length);if(!focusable.length){e.preventDefault();dialog.focus();return;}const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){e.preventDefault();first.focus();}});
function changePasswordDialog(){const dialog=$('#detail');dialog.dataset.kind='change-password';dialog.innerHTML=`<div class="dialog-head"><div><p class="eyebrow">ACCOUNT SECURITY</p><h2>Change your password</h2><p class="quiet-note">Update the password for your signed-in dashboard account.</p></div><button type="button" class="icon-button" data-action="close" aria-label="Close">×</button></div><div class="dialog-body"><form id="change-password-form" class="form-grid"><label>New password<input name="password" type="password" autocomplete="new-password" minlength="14" required></label><label>Confirm new password<input name="confirm_password" type="password" autocomplete="new-password" minlength="14" required></label><p class="quiet-note">Use a unique password with at least 14 characters. The dashboard applies its own password policy.</p><p id="change-password-result" class="quiet-note" role="status" aria-live="polite"></p><div class="dialog-actions"><button type="button" class="button secondary" data-action="close">Cancel</button><button class="button primary" type="submit">Update password</button></div></form></div>`;showDialog(dialog);}
window.addEventListener('hashchange',render);render();bootstrapCloud();

let inviteDialogShown=false;
function showInvitePasswordDialog(){if(!cloudEnabled||!backendClient||(!inviteFlowRequested&&!recoveryFlowRequested)||!cloudSession||inviteDialogShown)return;inviteDialogShown=true;const dialog=$('#detail'),recovery=recoveryFlowRequested;dialog.dataset.kind='invite-password';dialog.innerHTML=`<div class="dialog-head"><div><p class="eyebrow">${recovery?'PASSWORD RESET':'TEAM INVITATION'}</p><h2>${recovery?'Choose a new password':'Set your dashboard password'}</h2><p class="quiet-note">${recovery?'Choose a new private password for your account.':'Choose a private password to finish joining the team workspace.'}</p></div></div><div class="dialog-body"><form id="invite-password-form" class="form-grid"><label>New password<input name="password" type="password" minlength="14" autocomplete="new-password" required></label><label>Confirm password<input name="confirm_password" type="password" minlength="14" autocomplete="new-password" required></label><p class="quiet-note">Use a unique password with at least 14 characters.</p><p id="invite-password-result" class="quiet-note" role="status" aria-live="polite"></p><div class="dialog-actions"><button class="button primary" type="submit">${recovery?'Update password':'Save password'}</button>${recovery?'':'<button class="button secondary" type="button" data-action="cancel-invite">Sign out</button>'}</div></form></div>`;showDialog(dialog);}
backendClient?.auth.onAuthStateChange((_event,session)=>{if(session){cloudSession=session;setTimeout(showInvitePasswordDialog,0);}});
setTimeout(showInvitePasswordDialog,0);
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='change-password-form')return;e.preventDefault();const data=Object.fromEntries(new FormData(form).entries()),result=$('#change-password-result'),submit=form.querySelector('[type=submit]');if(data.password!==data.confirm_password){result.textContent='The passwords do not match.';return;}if(data.password.length<14){result.textContent='Use at least 14 characters.';return;}if(!backendClient||!cloudSession){result.textContent='Sign in again before changing your password.';return;}submit.disabled=true;submit.textContent='Updating…';const {error}=await backendClient.auth.updateUser({password:data.password});if(error){result.textContent=error.message;submit.disabled=false;submit.textContent='Update password';return;}form.reset();closeDialog($('#detail'));toast('Your password was updated.');});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id==='cloud-invite-form'){e.preventDefault();const data=Object.fromEntries(new FormData(form).entries()),result=$('#cloud-invite-result'),submit=form.querySelector('[type="submit"]');if(submit){submit.disabled=true;submit.textContent='Sending…';}if(result)result.textContent='';const {data:response,error}=await backendClient.functions.invoke('invite-team-member',{body:{display_name:data.display_name,email:data.email,role:data.role,finance_access:form.elements.finance_access.checked}});if(error||response?.error){if(result)result.textContent=response?.error||error?.message||'Could not send invitation.';if(submit){submit.disabled=false;submit.textContent='Send invitation';}return;}if(result)result.textContent=response.message||'Invitation sent.';form.reset();if(submit){submit.disabled=false;submit.textContent='Send invitation';}await loadCloudWorkspace();toast(response.message||'Invitation sent.');return;}if(form.id==='invite-password-form'){e.preventDefault();const data=Object.fromEntries(new FormData(form).entries()),result=$('#invite-password-result'),submit=form.querySelector('[type="submit"]');if(data.password!==data.confirm_password){if(result)result.textContent='The passwords do not match.';return;}if(data.password.length<14){if(result)result.textContent='Use at least 14 characters.';return;}if(submit){submit.disabled=true;submit.textContent='Saving…';}const {error}=await backendClient.auth.updateUser({password:data.password});if(error){if(result)result.textContent=error.message;if(submit){submit.disabled=false;submit.textContent='Save password';}return;}const url=new URL(location.href);url.searchParams.delete('invite');url.searchParams.delete('recover');history.replaceState({},'',url.pathname+(url.search||'')+'#overview');closeDialog($('#detail'));render();toast('Password saved. Your dashboard account is ready.');return;}});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(button?.dataset.action!=='cancel-invite')return;history.replaceState({},'',location.pathname+(location.search||'')+'#overview');await backendClient.auth.signOut();closeDialog($('#detail'));});
